@startuml

class Ingredient {
  + name : string
  + unit : string
  + stock : float
}

class Dish {
  + id : int
  + name : string
}

class IngredientDish {
  + quantity : float
}

class Table {
  + id : int
  + capacity : int
}

class Meal {
  + date : date
  + start_time : time
  + end_time : time
}

class DishMeal {
  + times_served : int
}

class Person {
  + name : string
  + address : string
}

class Client extends Person {
  + tax_id : string
}

class Waiter extends Person {
  + id : int
  + phone : string
}

Meal "1" -- "1" Table
Meal "1" -- "0..1" Client
Meal "1" -- "1" Waiter
Meal "*" -- "*" Dish : via DishMeal
Dish "*" -- "*" Ingredient : via IngredientDish

@enduml

